// Bundles db/migrations/*.sql into lib/migrations.generated.ts so that a Vercel function can
// apply them without reading the file system.  Runs before `next build`; `--check` exits 1
// when the generated file is stale (used by the tests).
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const dir = join(root, "db", "migrations");
const files = readdirSync(dir).filter((f) => /^\d{4}_[a-z0-9_]+\.sql$/.test(f)).sort();
const items = files.map((f) => ({ version: f.replace(/\.sql$/, ""), sql: readFileSync(join(dir, f), "utf8") }));
const out = `// GENERATED by scripts/gen-migrations.mjs from db/migrations/*.sql — do not edit.\n` +
  `export const MIGRATIONS: { version: string; sql: string }[] = ${JSON.stringify(items, null, 2)};\n`;
const target = join(root, "lib", "migrations.generated.ts");
if (process.argv.includes("--check")) {
  let cur = "";
  try { cur = readFileSync(target, "utf8"); } catch { /* missing */ }
  if (cur !== out) { console.error("lib/migrations.generated.ts is stale: run `pnpm migrations`"); process.exit(1); }
  console.log(`migrations bundle up to date (${items.length})`);
} else {
  writeFileSync(target, out);
  console.log(`bundled ${items.length} migration(s): ${items.map((i) => i.version).join(", ")}`);
}
